  "prompt": "prompts/physics_committee_luna_opening_v1.md",
  "rankings": [
    {
      "rank": 1,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED made individual superconducting artificial atoms controllable through microwave fields in a cavity and established a powerful new regime of quantum optics. Its foundational impact on quantum physics and quantum computing is exceptional.",
        "attribution": "Blais's theory and proposal, Wallraff's experimental demonstration, and Schoelkopf's development of the experimental architecture are a defensible three-person account. Steven M. Girvin's important theoretical contributions make the boundary of credit difficult.",
        "maturity": "The platform has been reproduced widely and has supported increasingly complex experiments and processors over many years.",
        "uncertainties": [
          "The discovery was a broad collaboration between theory and experiment, so limiting recognition to three people risks underrepresenting foundational contributors."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction and fault tolerance showed how quantum information can be protected in principle and transformed quantum computing from a fragile concept into a physically meaningful architecture. The theoretical foundations are profoundly influential.",
        "attribution": "Shor and Steane established early quantum error-correcting codes, while Kitaev developed influential topological codes and fault-tolerant ideas. The field's origins and advances involve many others, so this selection emphasizes foundational work.",
        "maturity": "The theory is established, and experiments have made substantial progress, but scalable fault-tolerant operation remains an active technical challenge.",
        "uncertainties": [
          "The timing of a prize may depend on how much weight is placed on the theoretical framework versus demonstration of large-scale fault tolerance."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions provided a precise, controllable realization of quantum computation and simulation, connecting foundational quantum information ideas with experimentally testable many-body physics.",
        "attribution": "Cirac and Zoller developed the influential theoretical proposal, and Blatt led landmark experimental demonstrations. This gives a clear theory-to-experiment attribution.",
        "maturity": "Ion control, entangling gates, and quantum simulation have been demonstrated reproducibly across laboratories over decades, though scaling remains challenging.",
        "uncertainties": [
          "The broader trapped-ion field includes additional foundational experimental contributors whose work is not represented in the proposed group."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B041",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks at 10^-18 precision opened a new level of timekeeping and made clocks powerful probes of fundamental physics, including tests of relativity and searches for varying constants.",
        "attribution": "Katori and Ye independently drove complementary approaches that established the field, making joint recognition well justified.",
        "maturity": "The precision has been achieved and independently confirmed, with sustained progress in clock performance and applications.",
        "uncertainties": [
          "A prize could be framed around clock development broadly, which raises questions about the boundary between these contributions and other precision-measurement work."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic crystals and photonic band gaps established a general way to shape light propagation and emission using periodic structures, with lasting consequences for optics and condensed matter concepts.",
        "attribution": "Yablonovitch and John independently articulated key routes to photonic band gaps, while Joannopoulos helped develop the theoretical framework and bring the subject to broad influence. Credit is shared across closely related early contributions.",
        "maturity": "The underlying physics is settled and the structures are widely studied and used, though applications vary in how transformative they have been.",
        "uncertainties": [
          "The discovery has multiple independent origins, making the most equitable division of credit difficult."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B012",
      "proposed_laureates": [
        "Ataç İmamoğlu",
        "Jörg Wrachtrup",
        "Ronald Hanson"
      ],
      "assessment": {
        "nobel_worthiness": "Optical interfaces to solid-state spins made individual spins addressable and connected them to photons, opening a route to quantum networks and new experiments in quantum information.",
        "attribution": "İmamoğlu's work helped establish optical control of solid-state quantum systems; Wrachtrup advanced single-spin optical detection and control; Hanson demonstrated important spin-photon and network capabilities. The credited contributions span distinct stages of the field.",
        "maturity": "Single-spin control and entanglement over optical links have been demonstrated, but practical, scalable networks remain under development.",
        "uncertainties": [
          "The broad discovery description combines several related advances, so a single award citation may not cleanly capture their distinct contributions."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B017",
      "proposed_laureates": [
        "Christophe Salomon",
        "John E. Thomas",
        "Rudolf Grimm"
      ],
      "assessment": {
        "nobel_worthiness": "Strongly interacting Fermi gases provided a clean, tunable setting for studying pairing and the BEC-BCS crossover, linking ultracold-atom physics to broader questions about quantum fluids.",
        "attribution": "Salomon, Thomas, and Grimm led influential experimental approaches to producing and probing these gases; the field grew through substantial parallel work by other groups.",
        "maturity": "The crossover and its key signatures have been studied extensively and reproduced across laboratories.",
        "uncertainties": [
          "The field's breadth makes it difficult to draw a sharp line around the specific realization or result that would anchor a prize."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B018",
      "proposed_laureates": [
        "Bart J. van Wees",
        "Henk van Houten",
        "Michael Pepper"
      ],
      "assessment": {
        "nobel_worthiness": "Conductance quantization in ballistic quantum point contacts was a striking demonstration of quantum transport at the device scale and became a foundational result in mesoscopic physics.",
        "attribution": "Van Wees and van Houten are closely associated with the influential observation and its interpretation; Pepper's earlier and related work on point contacts makes the precise division of credit complex.",
        "maturity": "The effect is robust, well understood, and repeatedly observed in semiconductor nanostructures.",
        "uncertainties": [
          "Independent and nearly concurrent experiments, along with prior point-contact work, complicate the attribution of a single discovery."
        ]
      }
    }
  ]
}
